 foreach(['barad_design','barad_logo_id','barad_phone','barad_mobile','barad_email','barad_address','barad_map_url','barad_hours','barad_local_page_id','barad_company_catalog_id','barad_company_catalog_cover_id','barad_catalog_contact_icons','barad_catalog_extended_pages','barad_catalog_extended_media','woocommerce_currency','woocommerce_price_num_decimals','woocommerce_price_decimal_sep','woocommerce_price_thousand_sep','woocommerce_currency_pos','woocommerce_tax_display_shop','permalink_structure','blogname','blogdescription','page_on_front','show_on_front'] as $key)$data['options'][$key]=get_option($key);
