 file_put_contents($root.'/content/site.json',wp_json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT));
 $routes=[];foreach($data['pages'] as $p)if($p['status']==='publish')$routes[]=$p['url'];foreach($data['products'] as $p)if($p['status']==='publish')$routes[]=$p['url'];foreach($data['terms'] as $t)if(($t['translation']['language']??'fa')==='fa'&&$t['taxonomy']==='product_cat')$routes[]=$t['url'];$routes=array_values(array_unique($routes));file_put_contents($root.'/content/routes.json',wp_json_encode($routes,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));
 $summary=['pages'=>count($data['pages']),'published_pages'=>count(array_filter($data['pages'],fn($p)=>$p['status']==='publish')),'products'=>count($data['products']),'published_products'=>count(array_filter($data['products'],fn($p)=>$p['status']==='publish')),'media'=>count($data['media']),'public_routes'=>count($routes),'excluded'=>['users','passwords','requests','orders','customer-data','license-files','wp-config','database','runtime']];file_put_contents($root.'/content/export-summary.json',wp_json_encode($summary,JSON_PRETTY_PRINT));echo wp_json_encode($summary).PHP_EOL;
